/* ============================================================
   brand.js — Identidad visual de Vivas CR
   El logotipo va incrustado como data-URI para que la app
   funcione sin conexión y en un único archivo.
   ============================================================ */
(function (A) {
  'use strict';

  A.brand = {
    mark96:  'data:image/png;base64,',   /* emblema para la barra superior */
    mark256: 'data:image/png;base64,',   /* emblema grande: portada, acceso, iconos */
    pdf: { b64: '', w: 260, h: 260 },   /* JPEG para incrustar en los PDF */

    colors: {
      cyan:  '#01C3FD',   /* aro y reflejos del logotipo */
      blue:  '#0076D9',   /* texto "Vivas CR" */
      deep:  '#063C6B',   /* azul profundo derivado, base corporativa */
      steel: '#64748B'
    }
  };
})(window.App);
